use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let str_input = input.as_str().unwrap();
    let mut chars = str_input.chars();
    let mut is_valid = true;
    while let Some(c) = chars.next() {
        if !c.is_alphabetic() && c != '_' && c != '_' {
            is_valid = false;
            break;
        }
    }
    Value::Bool(is_valid)
}
